#!/usr/bin/env bash
# Regenerates brotli_amalgamated.c (and its vendored header tree) from a fresh brotli checkout.
# Not run automatically by anything -- this is a one-off/occasional regeneration script, kept so the
# amalgamation is reproducible instead of being a hand-edited one-off. See README.md in this directory for
# why this file exists and what it's for.
#
# Usage: ./build_amalgamation.sh [path-to-brotli-checkout]
#   If no path is given, clones https://github.com/google/brotli.git into a temp dir and checks out the
#   pinned commit below.
set -euo pipefail

BROTLI_COMMIT=34f020fa9daba975747b29885314c2545b7aa040
HERE="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"

REPO="${1:-}"
CLEANUP=0
if [ -z "$REPO" ]; then
  REPO="$(mktemp -d)"
  CLEANUP=1
  git clone https://github.com/google/brotli.git "$REPO"
  git -C "$REPO" checkout "$BROTLI_COMMIT"
fi

ACTUAL_COMMIT="$(git -C "$REPO" rev-parse HEAD)"
if [ "$ACTUAL_COMMIT" != "$BROTLI_COMMIT" ]; then
  echo "warning: checkout at $REPO is commit $ACTUAL_COMMIT, not the pinned $BROTLI_COMMIT -- proceeding anyway, but brotli_amalgamated.c's header comment commit hash will no longer be accurate for what you just generated" >&2
fi

# The 12 real, unmodified source files this bug's call chain needs (confirmed sufficient across many rounds
# of this investigation -- docs/DESIGN.md Sec.22.288/291/299/301/308).
DEC_FILES="bit_reader decode huffman prefix state static_init"
COMMON_FILES="constants context dictionary platform shared_dictionary transform"

VENDOR="$HERE/vendor"
rm -rf "$VENDOR"
mkdir -p "$VENDOR/c/dec" "$VENDOR/c/common" "$VENDOR/c/include/brotli"

# Vendor the headers verbatim, preserving brotli's own c/dec, c/common, c/include/brotli layout -- this is
# what makes the .c files' own #include "foo.h" / #include "../common/foo.h" / #include <brotli/foo.h>
# directives resolve exactly as they do in a normal brotli build, with zero edits to any #include line.
cp "$REPO"/c/dec/*.h "$VENDOR/c/dec/"
cp "$REPO"/c/common/*.h "$VENDOR/c/common/"
cp "$REPO"/c/include/brotli/*.h "$VENDOR/c/include/brotli/"

# The amalgamated .c file lives at c/dec/ (matching where 6 of the 12 source files originally lived), so
# their "bit_reader.h"-style same-directory includes and "../common/foo.h"-style relative includes both
# resolve without rewriting anything. The 6 c/common/-origin files' own same-directory includes ("platform.h"
# etc.) are NOT found there directly, but fall through to the compiler's extra -I search path -- every
# consumer of this file must therefore compile with `-I <this dir>/vendor/c/common` in addition to
# `-I <this dir>/vendor/c/include` (see README.md for the exact command).
OUT="$VENDOR/c/dec/brotli_amalgamated.c"

{
  cat <<HEADER
/* brotli_amalgamated.c -- mechanical concatenation of 12 real, UNMODIFIED brotli source files.
 *
 * Source: https://github.com/google/brotli at commit $ACTUAL_COMMIT
 * Generated by: test/c/cve_repro/brotli_cve_2026_111497/build_amalgamation.sh (this directory)
 *
 * Files concatenated, in this order (each file's content below is pasted verbatim, byte-for-byte identical
 * to brotli's own source at the commit above -- no edits to brotli's own code, not even whitespace):
 *   c/dec/bit_reader.c
 *   c/dec/decode.c
 *   c/dec/huffman.c
 *   c/dec/prefix.c
 *   c/dec/state.c
 *   c/dec/static_init.c
 *   c/common/constants.c
 *   c/common/context.c
 *   c/common/dictionary.c
 *   c/common/platform.c
 *   c/common/shared_dictionary.c
 *   c/common/transform.c
 *
 * See the README.md next to this file for what this is for, the CVE-2026-111497 trigger input, and pointers
 * into docs/DESIGN.md for the full investigation history. Do not hand-edit this file -- regenerate it with
 * build_amalgamation.sh instead, so it stays a faithful, mechanical copy of real brotli source.
 */

HEADER
  for f in $DEC_FILES; do cat "$REPO/c/dec/$f.c"; echo; done
  for f in $COMMON_FILES; do cat "$REPO/c/common/$f.c"; echo; done
} > "$OUT"

echo "wrote $OUT ($(wc -l < "$OUT") lines)"

if [ "$CLEANUP" = 1 ]; then rm -rf "$REPO"; fi
